 samples=[json.loads(x) for x in (R/'resource_samples.jsonl').read_text().splitlines()];gaps=[(b['ns']-a['ns'])/1e9 for a,b in zip(samples,samples[1:])];active=[(b['native_clock']['active_ns']-a['native_clock']['active_ns'])/1e9 for a,b in zip(samples,samples[1:])];offset_growth=((samples[-1]['native_clock']['continuous_ns']-samples[-1]['native_clock']['active_ns'])-(samples[0]['native_clock']['continuous_ns']-samples[0]['native_clock']['active_ns']))/1e9
 assert all(not x['faults'] and x['allocated_bytes']<=500*1024**2 and x['new_evidence_allocated_bytes']<=150*1024**2 and all(b<2*1024**3 for b in x['rss_bytes'].values()) for x in samples)
